function App() {
  const [items] = useState([5, 3, 8, 1, 9, 2]);
  const [flag, setFlag] = useState(false);
  const sorted = useMemo(() => {
    // Pretend this is expensive.
    return [...items].sort((a, b) => a - b);
  }, [items]);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setFlag(f => !f)}>Toggle ({String(flag)})</button>
      <p>Sorted: {sorted.join(', ')}</p>
      <small style={{ color: '#6b7280' }}>Toggling does NOT re-sort — items didn't change.</small>
    </div>
  );
}

const Row = memo(function Row({ id, onSelect }) {
