const Chart = memo(function Chart({ config }) {
  const renders = useRef(0);
  renders.current++;
  return (
    <div style={{ padding: 8, border: '1px solid #d1d5db', borderRadius: 6, marginTop: 8 }}>
      Chart color: {config.color} — renders: {renders.current}
    </div>
  );
});

function App() {
  const [count, setCount] = useState(0);
  // FIX: stable object reference across renders.
  const config = useMemo(() => ({ color: 'blue' }), []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>
      <Chart config={config} />
    </div>
  );
}

const Row = memo(function Row({ item, onSelect }) {
  return <li onClick={() => onSelect(item)} style={{ cursor: 'pointer' }}>{item}</li>;
});

function App() {
  const [items] = useState(['apple', 'banana', 'cherry', 'date', 'fig']);
  const [query, setQuery] = useState('');
  const filtered = useMemo(
    () => items.filter(i => i.includes(query.toLowerCase())),
    [items, query]
  );
  const onSelect = useCallback((item) => console.log('selected', item), []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={query} onChange={e => setQuery(e.target.value)} placeholder="Filter..." />
      <ul>{filtered.map(item => <Row key={item} item={item} onSelect={onSelect} />)}</ul>
    </div>
  );
}

